INSERT OR IGNORE INTO ingestion_queue (id, url, title, abstract, source, reason, status) VALUES ('ingest-f4384269', 'https://www.theguardian.com/law/2026/mar/05/circumcision-classed-as-potentially-harmful-practice-in-new-cps-guidance', 'Circumcision classed as potentially harmful practice in new CPS guidance', 'This article details official guidance released by the Crown Prosecution Service (CPS) in England and Wales, which classifies non-therapeutic circumcision carried out under improper or non-sterile conditions as a potentially harmful practice subject to prosecution under offences against the person and child cruelty laws. The update reflects ongoing debates among prosecutors, human rights campaigners, and religious leaders concerning bodily integrity, legal regulation, and religious freedom.', 'The Guardian', 'Selected for its direct coverage of legal and institutional shifts in how state prosecutors classify non-medical male circumcision within bodily autonomy and child safeguarding frameworks.', 'pending');
INSERT OR IGNORE INTO ingestion_queue (id, url, title, abstract, source, reason, status) VALUES ('ingest-53032c52', 'https://www.timesofisrael.com/new-eu-circumcision-certification-program-looks-to-keep-brit-milah-safe-in-europe/', 'New EU circumcision certification program looks to keep brit milah safe in Europe', 'This report examines a new European-wide medical certification program launched by Jewish leadership organizations to standardize welfare and health credentials for traditional circumcisers (mohels). The initiative is designed to address legal challenges and law enforcement actions across EU member states where non-physician circumcisions face rising regulatory scrutiny.', 'The Times of Israel', 'Provides valuable documentation of how religious institutions adapt to emerging European legal standards regarding child welfare, medical licensing, and bodily rights.', 'pending');
INSERT OR IGNORE INTO ingestion_queue (id, url, title, abstract, source, reason, status) VALUES ('ingest-9d0d7f8d', 'https://pubmed.ncbi.nlm.nih.gov/38725000/', 'Parental awareness and practices regarding male circumcision timing, setting, and providers: a multicenter cross-sectional survey from Turkey (n = 637)', 'This multicenter study published in BMC Pediatrics investigates parental knowledge and practices regarding male circumcision, focusing on procedural timing and clinical environments. The researchers highlight a significant gap between parental awareness of the potential psychological risks associated with circumcising boys during sensitive early childhood development stages (ages 2–6) and actual clinical practices.', 'BMC Pediatrics / National Center for Biotechnology Information', 'Provides high-quality academic data on the psychological and cultural considerations surrounding the timing of male circumcision, making it an essential empirical source for archival research.', 'pending');
INSERT OR IGNORE INTO ingestion_queue (id, url, title, abstract, source, reason, status) VALUES ('ingest-8f86265a', 'https://reproductiverights.org/resources/bodily-autonomy-rights-under-threat/', 'Bodily Autonomy Rights Under Threat', 'This resource from the Center for Reproductive Rights analyzes state-level legislative proposals and legal protections across the United States regarding bodily autonomy and healthcare decision-making. The report establishes analytical frameworks for understanding how bodily integrity rights are protected, contested, and regulated across various medical contexts.', 'Center for Reproductive Rights', 'Offers essential legal and sociological grounding on broader bodily autonomy rights and public policy trends in the United States.', 'pending');
INSERT OR IGNORE INTO ingestion_queue (id, url, title, abstract, source, reason, status) VALUES ('ingest-5f2a7f18', 'https://intactamerica.org/blog/', 'Seeking the Truth: Why the U.S. circumcision rate matters', 'This organizational analysis by Intact America investigates contemporary national trends in U.S. infant male circumcision rates. The publication critically reviews public health reporting methodologies, examines cultural shifts away from routine neonatal cutting, and outlines advocacy strategies centered on child genital autonomy.', 'Intact America', 'Chosen as a direct publication from a key intactivist organization, reflecting current advocacy discourse and sociological perspectives on infant bodily integrity.', 'pending');
